/**
 * Bounded JSON scalar, not executable content. Strings at most 4096 code points; finite numbers in the JSON-safe
 * range.
 */
export type UIStreamScalar = null | boolean | number | string;

/**
 * Interaction value: scalar, scalar array or scalar map only (one container level). No functions, callbacks, binary
 * data or nested containers. Never send credentials or secret field contents.
 */
export type UIStreamValue = UIStreamScalar | UIStreamScalar[] | Record<string, UIStreamScalar>;

/**
 * Client opt-in for protocol 1 plus supported native component tags. ui_version alone does not opt in. Declaration is
 * not runtime support.
 */
export interface UIStreamCapability {
  protocol: 1;
  components: string[];
}

/**
 * Full authoritative tree before deltas, including after resume or recovery. Keys required on sections/items; tiles
 * and global uniqueness need semantic validation.
 */
export interface UIStreamSnapshot {
  protocol: 1;
  session: string;
  epoch: string;
  version: number;
  root_key: string;
  view: View;
}

/**
 * Atomic batch, at most 256 operations. An explicit empty batch keeps the version for a non-event no-op or advances
 * exactly one revision as an accepted or ambiguous callback fence. Validate against a staged whole tree before
 * committing. Ordering/equality are reducer checks.
 */
export interface UIStreamDelta {
  protocol: 1;
  session: string;
  epoch: string;
  base_version: number;
  version: number;
  operations: UIStreamOperation[];
}

/**
 * Authenticated owner interaction for the displayed generation/version. Deduplicate event_id before writes. Validate
 * action against the saved node/event slot, then resolve its callback server-side; no callback code or secrets in
 * this payload.
 */
export interface UIStreamEvent {
  protocol: 1;
  session: string;
  epoch: string;
  version: number;
  event_id: string;
  key: string;
  /**
   * Opaque registered callback Action.id for this node and event slot; never callback code or an authority claim.
   */
  action: string;
  event: string;
  value: UIStreamValue;
}

/**
 * Atomic native tree operation. Unknown operations invalidate the entire batch and require a snapshot, never
 * skipping. Tiles update by replacing their containing grid/carousel.
 */
export type UIStreamOperation =
  | UIStreamReplace
  | UIStreamInsert
  | UIStreamRemove
  | UIStreamMove;
export const UISTREAM_OPERATION_OPS = ["replace", "insert", "remove", "move"] as const;

/**
 * Replace a complete node/subtree; omitted properties are cleared. Exactly one payload, matching the target kind and
 * key.
 */
export type UIStreamReplace = {
  op: "replace";
  key: string;
} & (
  | { view: View; section?: never; item?: never }
  | { view?: never; section: Section; item?: never }
  | { view?: never; section?: never; item: Component }
);

/**
 * Insert a section under root or item under section. before names a destination sibling; omitted means append.
 */
export type UIStreamInsert = {
  op: "insert";
  parent: string;
  before?: string;
} & (
  | { section: Section; item?: never }
  | { section?: never; item: Component }
);

/**
 * Remove a node and its subtree, never the root. Existence/root checks are semantic.
 */
export interface UIStreamRemove {
  op: "remove";
  key: string;
}

/**
 * Move a section/item subtree. No cycles, tile moves or wrong parent kinds. Omitted before appends.
 */
export interface UIStreamMove {
  op: "move";
  key: string;
  parent: string;
  before?: string;
}

/**
 * Owner-bound lifecycle request over the authenticated WebSocket. The transport supplies principal/hub identity;
 * never trust an owner field from JSON. No endpoint or runtime is enabled by these contracts.
 */
export type UIStreamRequest =
  | UIStreamOpenRequest
  | UIStreamCloseRequest
  | UIStreamSuspendRequest
  | UIStreamResumeRequest
  | UIStreamEventRequest
  | UIStreamSnapshotRequest;
export const UISTREAM_REQUEST_REQUESTS = ["open", "close", "suspend", "resume", "event", "snapshot"] as const;

/**
 * Reauthorize the extension/contribution and explicit context.stream capability; allocate an owner-bound session and
 * send a snapshot before deltas.
 */
export interface UIStreamOpenRequest {
  request: "open";
  protocol: 1;
  request_id: string;
  extension: string;
  contribution: string;
  context: UIContext;
  state: string;
}

/**
 * Idempotent for unknown/already closed owned sessions; unmount and release state, callbacks and effects.
 */
export interface UIStreamCloseRequest {
  request: "close";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
}

/**
 * Stop UI intervals/polling and bound pending work. Service work is independent of visibility.
 */
export interface UIStreamSuspendRequest {
  request: "suspend";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
}

/**
 * Reauthorize the owned session, discard stale delta chains and send a fresh snapshot before further deltas.
 */
export interface UIStreamResumeRequest {
  request: "resume";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
  version: number;
}

/**
 * Authorize and deduplicate the interaction before invoking its registered server-side callback. request_id is
 * correlation, not write deduplication.
 */
export interface UIStreamEventRequest {
  request: "event";
  protocol: 1;
  request_id: string;
  interaction: UIStreamEvent;
}

/**
 * Read-only recovery request: reauthorize and send a complete snapshot, never replay an interaction or write.
 */
export interface UIStreamSnapshotRequest {
  request: "snapshot";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
  version: number;
}

export type UIStreamClientEnvelope = {
  type: "extension_ui_stream";
  manager?: string;
} & (
  | { request: UIStreamRequest }
);

/**
 * Bounded presentation-only subset of native ActionResult, at most 64 KiB UTF-8 JSON. Carried in the correlated event
 * receipt and cached on replay. Clients apply it once per session/epoch/event_id, only after reaching
 * receipt.version; never execute HTML, JavaScript or infer authorization from a result. JSX state owns view/items
 * updates through snapshots/deltas. Manager validates push ownership and credential-free HTTPS (or its own permitted
 * native URL).
 */
export interface UIStreamActionResult {
  toast?: string;
  open_url?: string;
  push?: UIStreamPush;
  pop?: boolean;
  lines?: UIStreamFileLines;
}

/**
 * Extension-owned native Push only: no assistant page or arbitrary target. State is additionally bounded to 16 KiB
 * UTF-8. Not authority to invoke an action.
 */
export interface UIStreamPush {
  ui?: string;
  state?: string;
  title?: string;
}

/**
 * Native FileLines presentation response correlated to the saved event, not filesystem access or code execution. The
 * complete result remains limited to 64 KiB UTF-8 JSON.
 */
export interface UIStreamFileLines {
  path: string;
  side?: DiffSide;
  start: number;
  lines: string[];
  total?: number;
}

export interface UIStreamReceipt {
  session: string;
  epoch: string;
  event_id: string;
  version: number;
  status: string;
  result?: UIStreamActionResult;
}

export interface UIStreamFailure {
  code: string;
  message: string;
}

export interface UIStreamSnapshotEnvelope {
  kind: "snapshot";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  snapshot: UIStreamSnapshot;
}

export interface UIStreamDeltaEnvelope {
  kind: "delta";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  delta: UIStreamDelta;
}

export interface UIStreamReceiptEnvelope {
  kind: "receipt";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  receipt: UIStreamReceipt;
}

export interface UIStreamErrorEnvelope {
  kind: "error";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  error: UIStreamFailure;
}

export interface UIStreamClosedEnvelope {
  kind: "closed";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  session: string;
}

export type UIStreamServerEnvelope =
  | UIStreamSnapshotEnvelope
  | UIStreamDeltaEnvelope
  | UIStreamReceiptEnvelope
  | UIStreamErrorEnvelope
  | UIStreamClosedEnvelope
  | UIStreamSuspendedEnvelope;
export const UISTREAM_SERVER_ENVELOPE_KINDS = ["snapshot", "delta", "receipt", "error", "closed", "suspended"] as const;

export interface UIStreamSuspendedEnvelope {
  kind: "suspended";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  session: string;
}

/**
 * Source-process native render revision, independent of manager-owned wire revisions. Validate original JSON before
 * fitting; never trust source recipients or owners.
 */
export interface UIPageSnapshot {
  generation: string;
  version: number;
  rootKey: string;
  view: View;
}

/**
 * error.code of the transcription calls besides permission_denied (data {scope: "transcription"}): invalid_params (a
 * field missing or wrong, audio that is not base64 PCM16 or over 256 KiB a call, a job that is not this extension's
 * or no longer runs); assistant_offline (the manager is away: try again); transcription_unavailable (no transcription
 * is chosen, ready or able to replay: the owner sets it up in Settings › Meetings); busy (this extension has a job
 * running, or two extensions have); too_long (more than 15 minutes of audio: the job is ended); timeout (the
 * transcription stopped answering: the job is ended); transcription_failed (the transcription failed the job; data
 * {code}: its error code).
 */
export type TranscriptionErrorCode = "invalid_params" | "assistant_offline" | "transcription_unavailable" | "busy" | "too_long" | "timeout" | "transcription_failed" | (string & {});
export const TRANSCRIPTION_ERROR_CODES = ["invalid_params", "assistant_offline", "transcription_unavailable", "busy", "too_long", "timeout", "transcription_failed"] as const;

/**
 * transcription.start: a job for one piece of audio.
 */
export interface TranscriptionStartParams {
  /**
   * A BCP 47 hint (zh-CN, en-US); the transcription still follows the speech. Empty: the transcription's own guess.
   */
  language?: string;
  /** A short name of what this is, for the manager's log (its first 40 characters); never what is said. */
  label?: string;
}

export interface TranscriptionStartResult {
  /** The job's id, for the calls after; it is this extension's only. */
  job: string;
}

/**
 * transcription.audio: the next piece of the audio, contiguous with the last: PCM16 little-endian, mono, 16 kHz,
 * base64 (standard, with padding), at most 256 KiB of PCM (8 seconds) a call. The call returns once the audio is with
 * the transcription and no more than 60 seconds wait ahead of it, so sending as fast as it returns paces the job.
 */
export interface TranscriptionAudioParams {
  job: string;
  data: string;
}

/**
 * transcription.finish (every piece is sent: wait for the text) and transcription.cancel (drop the job and its text).
 */
export interface TranscriptionJobParams {
  job: string;
}

/**
 * One sentence, from and to in seconds from the start of the audio.
 */
export interface TranscriptionSegment {
  from: number;
  to: number;
  text: string;
}

/**
 * A span the transcription did not trust any text for (its sessions did not agree: noise, music, crosstalk): say so,
 * never guess.
 */
export interface TranscriptionGap {
  from: number;
  to: number;
}

export interface TranscriptionFinishResult {
  segments: TranscriptionSegment[];
  gaps?: TranscriptionGap[];
  /** How much audio the job took. */
  seconds: number;
}

/**
 * error.code a provider answers besides the base ErrorCode: not_found (no such repository or link, or the account it
 * uses cannot see it), not_signed_in (the user has to sign in to the source first), refused (the source said no: say
 * why in message), failed (anything else, say why in message). The manager shows the message on one line, clipped.
 */
export type RepoErrorCode = "not_found" | "not_signed_in" | "refused" | "failed" | (string & {});
export const REPO_ERROR_CODES = ["not_found", "not_signed_in", "refused", "failed"] as const;

/**
 * repo.parse: what repository an address on one of the contribution's hosts names (a web address, an https clone
 * address, ssh://git@host/... or git@host:...). Answer only from the address when it can; the manager asks repo.check
 * before it saves one.
 */
export interface RepoParseParams {
  /** The repository_providers item's id. */
  contribution: string;
  /** The address as the user or an Agent wrote it (an Agent's may be any page on the contribution's hosts). */
  url: string;
}

/**
 * The repository the address names. instance_url is exactly https://<host> or https://<host>:<port>, a lowercase host
 * the contribution claims and nothing after it; the default port is left out (https://code.acme.test, never
 * https://code.acme.test:443, which is refused), path its plain segments without a leading or trailing /
 * (acme/tools), canonical_url exactly instance_url + "/" + path.
 */
export interface RepoParseResult {
  instance_url: string;
  path: string;
  canonical_url: string;
  /**
   * How to clone it when that is not canonical_url: https or ssh on one of the contribution's hosts, no credentials,
   * query or fragment.
   */
  clone_url?: string;
  /** A name for people (Acme Tools): the catalog's default name for it. */
  display_name?: string;
}

/**
 * repo.check: whether the repository exists and the account the program uses can see it, before the manager saves it.
 * Answered with Empty, or not_found / not_signed_in / refused / failed.
 */
export interface RepoCheckParams {
  /** The repository_providers item's id. */
  contribution: string;
  /** The repository's canonical_url as repo.parse answered it. */
  canonical_url: string;
}

/**
 * A saved repository of the provider's, as repo.parse answered it.
 */
export interface RepoIdentity {
  instance_url: string;
  path: string;
  canonical_url: string;
}

/**
 * repo.link: one of the repository's issues or pull requests for a to-do, named by an address (url) or by kind and
 * number. The manager asks only for a link it has not stored yet.
 */
export interface RepoLinkParams {
  /** The repository_providers item's id. */
  contribution: string;
  repo: RepoIdentity;
  /**
   * The link's address as the user or an Agent wrote it; empty when kind and number name it. The hub only checks that
   * the answer is under repo, so answer the link this address names, or an error when it names none.
   */
  url?: string;
  /** With number, when there is no url: the answer must be this kind. */
  kind?: RepositoryLinkKind;
  /** With kind: the answer must have this number. */
  number?: string;
}

/**
 * The link: its kind and number, and its canonical address under the repository's canonical_url (https, no
 * credentials, query or fragment).
 */
export interface RepoLinkResult {
  kind: RepositoryLinkKind;
  number: string;
  canonical_url: string;
  /** Its title when the program knows it; kept on one line. */
  title?: string;
}

/**
 * repo.describe (optional): the title and state of a link the manager has stored, by its canonical address.
 */
export interface RepoDescribeParams {
  /** The repository_providers item's id. */
  contribution: string;
  /** The link's canonical_url as repo.link answered it. */
  canonical_url: string;
}

/**
 * What the link is called and where it stands.
 */
export interface RepoDescribeResult {
  /** Kept on one line. */
  title: string;
  /** Left out when the source has no such word for it. */
  state?: string;
}

/**
 * repo.pr_status (optional; capabilities pr_status, #11584): where a pull request the manager has stored stands, for
 * delivery checks and the status sweep, by its canonical address. Asked about pull_request links only, at most about
 * once a minute each. Answer with the program's own credentials; nothing of the answer reaches a model but its state.
 */
export interface RepoPRStatusParams {
  /** The repository_providers item's id. */
  contribution: string;
  /** The link's canonical_url as repo.link answered it. */
  canonical_url: string;
}

/**
 * The pull request's state; the rest when the source says it. A value that breaks its rule is dropped, a state
 * outside the enum fails the answer.
 */
export interface RepoPRStatusResult {
  state: string;
  /** The commit its merge made (merged only). */
  merge_commit?: string;
  /** Its head commit. */
  head_sha?: string;
  /** Its source branch. */
  head_ref?: string;
  /** Its target branch. */
  base_ref?: string;
  /** Who opened it, as the source names accounts. */
  author?: string;
  /** Whether the account the program uses opened it; left out when it cannot tell. */
  viewer_is_author?: boolean;
}

/**
 * error.code a memory source answers besides the base ErrorCode: not_ready (its entries are not loaded yet; the
 * manager uses none of them this time and asks again at the next assembly), failed (anything else, say why in
 * message).
 */
export type MemoryErrorCode = "not_ready" | "failed" | (string & {});
export const MEMORY_ERROR_CODES = ["not_ready", "failed"] as const;

/**
 * memory.entries: one page of the contribution's entries, most important first (standing ones first, then by rank,
 * then newest). Read-only: answering changes nothing in the program's state.
 */
export interface MemoryEntriesParams {
  /** The memory_sources item's id. */
  contribution: string;
  /**
   * At most this many entries on the page (the manager asks 200). Only a cap: the program ends a page early, with
   * has_more and after, so the answer stays within 1 MB.
   */
  limit: number;
  /** The previous page's after, to read on; empty for the first page. */
  after?: string;
}

/**
 * One page of entries. tagged is the program's promise for the whole page: it writes origin_space and categories on
 * every entry and leaves them out only when empty, so a missing origin_space means the main space and missing
 * categories mean general. A program that cannot promise that answers tagged false, and the manager then takes none
 * of its entries for its own track (each is in no track, not known, so the strictest rule holds).
 */
export interface MemoryEntriesResult {
  entries: MemoryEntry[];
  tagged: boolean;
  /**
   * Another page follows; ask again with after. When true, after must be set: true with an empty after counts as the
   * end of the entries.
   */
  has_more: boolean;
  /** Opaque: what to send as after for the next page; required in practice whenever has_more is true. */
  after?: string;
  /**
   * The bytes of standing entries' text the program wants a standing channel to carry (its own setting, say). The hub
   * keeps this budget apart from its own memory ledger's and takes the largest any page states; it caps it at 8192,
   * or at the owner's choice of 8192 or 16384 bytes when larger (assistant.memory_extension_standing_bytes: 4096 by
   * default, 8192 or 16384); left out or 0: that choice, 4096 by default. Entries past it are left out, the most
   * important kept.
   */
  standing_bytes?: number;
}

/**
 * One entry as the program keeps it. Only an active entry is carried; the others may be answered (so a page's order
 * stays the program's) and are skipped. An entry that breaks a rule here is dropped alone, never the page.
 */
export interface MemoryEntry {
  /**
   * Stable across pages and answers: a to-do's brief names the entries it carried by it (prefixed memory-extension:).
   */
  id: string;
  /** What the entry says, as the program would render it, on one or a few lines. */
  text: string;
  /**
   * The program's own grouping (preferences, workflow, people…). Used for explicit recall tag matching; it does not
   * change priority or visibility.
   */
  facet?: string;
  /**
   * active: the program would use it today, whatever it calls that state itself (a program with its own stable or
   * shifting states answers active for both); candidate: not borne out yet; dormant: not seen lately; retired: no
   * longer true. Only active entries are carried; an entry with any other value is dropped.
   */
  status: string;
  /** The slug of the space the entry was first said in; left out for the main space. */
  origin_space?: string;
  /**
   * Its information categories (health, finance, relationships, emotion, legal_id); left out for a general entry. A
   * category the hub does not know makes the entry not known.
   */
  categories?: string[];
  /**
   * The program kept it in every conversation (always in context). Only a standing entry goes to a standing channel
   * (usage still decides); the others come in only by relevance (their subjects or text) in a recall, a hand-off or
   * the Inbox.
   */
  standing?: boolean;
  /** The program's order among entries alike in standing: higher first. Left out: 0. */
  rank?: number;
  /**
   * The names whose mention brings the entry in (a person, a project, a place): what a task's or a message's words
   * are matched with, besides its text.
   */
  subjects?: string[];
}

/**
 * Whether the provider can work on this computer: ready; needs_install (its tool is not on the computer: the first
 * offload asks to install it, OffloadTool); needs_setup (the user has to set it up first, in the extension's
 * settings: detail says what); unavailable (detail says why).
 */
export type OffloadState = "ready" | "needs_install" | "needs_setup" | "unavailable" | (string & {});
export const OFFLOAD_STATES = ["ready", "needs_install", "needs_setup", "unavailable"] as const;

/**
 * What an offloaded item was: a file, a dir (folder), an app, an app's data (app_data), a bundle of items moved
 * together, a session archive, or other.
 */
export type OffloadItemKind = "file" | "dir" | "app" | "app_data" | "bundle" | "session" | "other" | (string & {});
export const OFFLOAD_ITEM_KINDS = ["file", "dir", "app", "app_data", "bundle", "session", "other"] as const;

/**
 * What offload.run does: offload (move paths away) or restore (bring items back by id).
 */
export type OffloadAction = "offload" | "restore" | (string & {});
export const OFFLOAD_ACTIONS = ["offload", "restore"] as const;

/**
 * offload.run's answer: started (a job runs: job), needs_install (the tool is missing and install was not given:
 * nothing happened; tool), refused (nothing happened; items say why), ok (a dry run's answer: items).
 */
export type OffloadRunStatus = "started" | "needs_install" | "refused" | "ok" | (string & {});
export const OFFLOAD_RUN_STATUSES = ["started", "needs_install", "refused", "ok"] as const;

/**
 * A job: running, done, failed (error says why) or canceled.
 */
export type OffloadJobState = "running" | "done" | "failed" | "canceled" | (string & {});
export const OFFLOAD_JOB_STATES = ["running", "done", "failed", "canceled"] as const;

/**
 * What a running job does now: install (its tool), check, upload, verify, cleanup (removing the originals), download
 * (a restore).
 */
export type OffloadPhase = "install" | "check" | "upload" | "verify" | "cleanup" | "download" | (string & {});
export const OFFLOAD_PHASES = ["install", "check", "upload", "verify", "cleanup", "download"] as const;

/**
 * One item of a job: pending, running, done, failed or skipped.
 */
export type OffloadJobItemStatus = "pending" | "running" | "done" | "failed" | "skipped" | (string & {});
export const OFFLOAD_JOB_ITEM_STATUSES = ["pending", "running", "done", "failed", "skipped"] as const;

/**
 * The program the provider needs on the computer. source is one sentence in the caller's language saying where it
 * comes from and where it is installed; the install confirmation shows it.
 */
export interface OffloadTool {
  name: string;
  title?: string;
  version?: string;
  installed: boolean;
  source?: string;
  detail?: string;
}

/**
 * One item the provider holds of this computer. bytes is the size it had on disk, what the map draws so both sides
 * share one scale; stored_bytes what it takes where it is stored; origin_path where it was and where a restore puts
 * it; stub_path the placeholder left behind, if any; local_bytes what of it is still on the computer (a cache). Times
 * are Unix seconds.
 */
export interface OffloadItem {
  id: string;
  name: string;
  kind: OffloadItemKind;
  bytes: number;
  stored_bytes?: number;
  origin_path?: string;
  stub_path?: string;
  local_bytes?: number;
  offloaded_at?: number;
  used_at?: number;
  /** Items moved together share a group (an app and its data). */
  group?: string;
  restorable: boolean;
}

/**
 * What the inventory left out past its 500 largest items.
 */
export interface OffloadMore {
  count: number;
  bytes: number;
}

/**
 * offload.inventory: what the provider holds of machine. refresh asks it not to answer from its own cache.
 */
export interface OffloadInventoryParams {
  contribution: string;
  locale: string;
  machine: UIMachine;
  refresh?: boolean;
}

/**
 * What the provider holds of the computer, largest first, at most 500 items (the rest summed in more). at is when it
 * was read (Unix seconds); total_bytes the items' bytes together, stored_bytes what they take where they are stored;
 * partial when the list may be incomplete. items may be left out when there are none; the manager's answer to the
 * apps always has it.
 */
export interface OffloadInventory {
  state: OffloadState;
  detail?: string;
  tool?: OffloadTool;
  at: number;
  total_bytes: number;
  stored_bytes?: number;
  partial?: boolean;
  items?: OffloadItem[];
  more?: OffloadMore;
}

/**
 * offload.run: offload paths (absolute, on machine, each already agreed by the node's protection rules) or restore
 * items (ids of the inventory), at most 50. dry_run only checks and answers status ok with each item; install lets
 * the job install the tool first (the user agreed to that too). request_id is the same for a retry of the same
 * request.
 */
export interface OffloadRunParams {
  contribution: string;
  locale: string;
  machine: UIMachine;
  action: OffloadAction;
  paths?: string[];
  items?: string[];
  dry_run?: boolean;
  install?: boolean;
  request_id: string;
}

/**
 * One path or item of a run's answer: why it is refused (reason, in the caller's language), or a dry run's verdict
 * (ok, bytes). refusal is set only by the manager, when the computer's own protection rules refused the path before
 * the program was asked (a machine.storage.check refusal code: credentials, app_managed, ...).
 */
export interface OffloadRunItem {
  path?: string;
  id?: string;
  ok?: boolean;
  reason?: string;
  refusal?: string;
  bytes?: number;
}

/**
 * offload.run's answer (OffloadRunStatus).
 */
export interface OffloadRunResult {
  status: OffloadRunStatus;
  job?: string;
  tool?: OffloadTool;
  items?: OffloadRunItem[];
}

/**
 * offload.job and offload.cancel: the job offload.run started.
 */
export interface OffloadJobParams {
  contribution: string;
  locale: string;
  machine: UIMachine;
  job: string;
}

/**
 * One path (offload) or item (restore) of a job.
 */
export interface OffloadJobItem {
  path?: string;
  id?: string;
  status: OffloadJobItemStatus;
  error?: string;
  bytes?: number;
}

/**
 * How a job goes. A job belongs to the extension: a client that lost track asks the inventory again. items may be
 * left out; the manager's answer to the apps always has it.
 */
export interface OffloadJob {
  state: OffloadJobState;
  phase?: OffloadPhase;
  done_bytes: number;
  total_bytes: number;
  freed_bytes?: number;
  error?: string;
  items?: OffloadJobItem[];
}

/**
 * One enabled disk_offload contribution, as GET /api/v1/extensions/-/offload lists it for the apps.
 */
export interface OffloadProvider {
  extension: string;
  id: string;
  name: string;
  kinds: DiskOffloadKind[];
  restore: boolean;
}

/**
 * GET /api/v1/extensions/-/offload?machine=: the providers the map can offer on that computer.
 */
export interface OffloadProviders {
  providers: OffloadProvider[];
}

/**
 * POST /api/v1/extensions/{id}/-/offload/{cid}/run, an app's request: without dry_run or confirm it is refused
 * (confirmation_required); install only after the user agreed to the tool's install confirmation.
 */
export interface OffloadRunRequest {
  machine: string;
  action: OffloadAction;
  paths?: string[];
  items?: string[];
  dry_run?: boolean;
  confirm?: boolean;
  install?: boolean;
}

/**
 * The run route's 202 answer: the job to follow with GET …/jobs/{job}.
 */
export interface OffloadStarted {
  job: string;
}

/**
 * An offload route's error: error in the reader's language and a code (bad_request, confirmation_required, read_only,
 * not_found, machine_offline, node_outdated, tool_install_required with tool, offload_refused with items,
 * plugin_failed (detail: the provider's own words, one line), usage_failed, deadline).
 */
export interface OffloadError {
  error: string;
  code: string;
  tool?: OffloadTool;
  detail?: string;
  items?: OffloadRunItem[];
}

export interface RoutineFactsParams {
  contribution: RoutineContributionID;
  /** Calendar date in the routine's time zone. */
  date: string;
  language: string;
}

export interface RoutineReportSection {
  title: string;
  /** Plain text. The host owns report layout. */
  body: string;
}

/**
 * A read-only snapshot. Return an empty object when the contribution has nothing for this date.
 */
export interface RoutineFactsResult {
  facts?: string[];
  sections?: RoutineReportSection[];
}

/** One call or event of an extension point's protocol: who sends it, and the definitions its params and
 * its answer hold to (no result: any JSON; an event has no answer). */
export interface Call {
  from: "hub" | "program";
  params: string;
  result?: string;
  event?: boolean;
}

